import Foundation
import Testing
@testable import CtrlKD

/// Equivalence proof against `Resources/job-003-vectors.json` — machine-generated by
/// the Python ctrl-kd 1.1.3 implementation. Every vector must reproduce exactly.
///
/// `Foundation` is imported here for `JSONDecoder`/`Bundle` only; the `CtrlKD` library
/// target itself stays Foundation-free.

private struct VectorFile: Decodable {
    let detect: [DetectVector]
    let linesPass: [LinesPassVector]
    let note: String

    enum CodingKeys: String, CodingKey {
        case detect
        case linesPass = "lines_pass"
        case note
    }
}

private struct DetectVector: Decodable {
    let inputHex: String
    let variant: String
    // Absent for the empty / ^Z-at-start vectors: Python's detect() returns those before
    // it computes any evidence, so there is nothing to assert for them.
    let softReturns: Int?
    let hardReturns: Int?
    let highBitBytes: Int?
    let textPct: Int?
    let symmetricBlocks1D: Int?
    let size: Int?

    enum CodingKeys: String, CodingKey {
        case inputHex = "input_hex"
        case variant
        case softReturns = "soft_returns"
        case hardReturns = "hard_returns"
        case highBitBytes = "high_bit_bytes"
        case textPct = "text_pct"
        case symmetricBlocks1D = "symmetric_blocks_1d"
        case size
    }
}

private struct LinesPassVector: Decodable {
    let inputHex: String
    let margin: Int
    let lines: [LineVector]

    enum CodingKeys: String, CodingKey {
        case inputHex = "input_hex"
        case margin
        case lines
    }
}

private struct LineVector: Decodable {
    let textHex: String
    let sep: String

    enum CodingKeys: String, CodingKey {
        case textHex = "text_hex"
        case sep
    }
}

private func loadVectors() throws -> VectorFile {
    let url = try #require(
        Bundle.module.url(forResource: "job-003-vectors", withExtension: "json"),
        "job-003-vectors.json missing from the test bundle"
    )
    return try JSONDecoder().decode(VectorFile.self, from: Data(contentsOf: url))
}

private func bytesFromHex(_ hex: String) -> [UInt8] {
    let chars = Array(hex)
    precondition(chars.count % 2 == 0, "hex string must have an even length")
    var out: [UInt8] = []
    out.reserveCapacity(chars.count / 2)
    for i in stride(from: 0, to: chars.count, by: 2) {
        out.append(UInt8(String(chars[i...(i + 1)]), radix: 16)!)
    }
    return out
}

private func hexFromBytes(_ bytes: [UInt8]) -> String {
    bytes.map { String(format: "%02x", $0) }.joined()
}

@Test func detectMatchesPythonVectors() throws {
    let vectors = try loadVectors().detect
    #expect(vectors.count == 7)
    for (i, v) in vectors.enumerated() {
        let got = detect(bytesFromHex(v.inputHex))
        #expect(got.variant.rawValue == v.variant, "detect vector \(i): variant")
        if let expected = v.softReturns {
            #expect(got.softReturns == expected, "detect vector \(i): soft_returns")
        }
        if let expected = v.hardReturns {
            #expect(got.hardReturns == expected, "detect vector \(i): hard_returns")
        }
        if let expected = v.highBitBytes {
            #expect(got.highBitBytes == expected, "detect vector \(i): high_bit_bytes")
        }
        if let expected = v.textPct {
            #expect(got.textPct == expected, "detect vector \(i): text_pct")
        }
        if let expected = v.symmetricBlocks1D {
            #expect(got.symmetricBlocks1D == expected, "detect vector \(i): symmetric_blocks_1d")
        }
        if let expected = v.size {
            #expect(got.size == expected, "detect vector \(i): size")
        }
    }
}

@Test func linesPassMatchesPythonVectors() throws {
    let vectors = try loadVectors().linesPass
    #expect(vectors.count == 8)
    for (i, v) in vectors.enumerated() {
        let got = linesPass(bytesFromHex(v.inputHex))
        #expect(got.margin == v.margin, "lines_pass vector \(i): margin")
        #expect(got.lines.count == v.lines.count, "lines_pass vector \(i): line count")
        for (j, expected) in v.lines.enumerated() where j < got.lines.count {
            let line = got.lines[j]
            #expect(line.separator.rawValue == expected.sep,
                    "lines_pass vector \(i) line \(j): sep")
            #expect(hexFromBytes(line.text) == expected.textHex,
                    "lines_pass vector \(i) line \(j): text")
        }
    }
}
